# Triton kernel function that increments an integer and stores it
@triton.jit
def function_1(i):
    i = i + 1
    i = function_2(i)
    return i

# Triton kernel function that increments an integer
@triton.jit
def function_2(i):
    i = i + 1
    return i

# Triton kernel that uses function_1 and stores the result
@triton.jit
def kernel(X, i, BLOCK: tl.constexpr):
    i = i + 1
    i = function_1(i)
    tl.store(X, i)

# Triton kernel with no specialization
@triton.jit(do_not_specialize=["i"])
def kernel_nospec(X, i, BLOCK: tl.constexpr):
    i = i + 1
    i = function_1(i)
    tl.store(X, i)

# Test function to check kernel reuse
def test_reuse():
    counter = 0

    def inc_counter(*args, **kwargs):
        nonlocal counter
        counter += 1
    triton.runtime.jit.JITFunction.cache_hook = inc_counter
    reset_tmp_dir()
    x = torch.empty(1, dtype=torch.int32, device='cuda')
    for i in range(10):
        kernel[(1,)](x, 1, BLOCK=1024)
    assert counter == 1

