import triton
import triton.language

# Kernel to compute the absolute value of a tensor
@triton.jit
def abs(x):
    return triton.language.where(x >= 0, x, -x)

# Kernel to compute the ceiling division of two tensors
@triton.jit
def cdiv(x, div):
    return (x + div - 1) // div

# Kernel to compute the element-wise minimum of two tensors
@triton.jit
def minimum(x, y):
    return triton.language.where(x < y, x, y)

# Kernel to compute the element-wise maximum of two tensors
@triton.jit
def maximum(x, y):
    return triton.language.where(x > y, x, y)

# Kernel to compute the sigmoid function of a tensor
@triton.jit
def sigmoid(x):
    return 1 / (1 + triton.language.exp(-x))

# Kernel to compute the softmax function of a tensor
@triton.jit
def softmax(x, ieee_rounding=False):
    z = x - triton.language.max(x, 0)
    num = triton.language.exp(z)
    den = triton.language.sum(num, 0)
    return triton.language.fdiv(num, den, ieee_rounding)

# Kernel to flatten a tensor
@triton.jit
def ravel(x):
    return triton.language.view(x, [x.numel])

# Kernel to transform indices of a matrix
@triton.jit
def swizzle2d(i, j, size_i, size_j, size_g):
    ij = i * size_j + j
    size_gj = size_g * size_j
    group_id = ij // size_gj
    off_i = group_id * size_g
    size_g = minimum(size_i - off_i, size_g)
    new_i = off_i + (ij % size_g)
    new_j = (ij % size_gj) // size_g
    return new_i, new_j

# Kernel to create a tensor filled with zeros
@triton.jit
def zeros(shape, dtype):
    return triton.language.full(shape, 0, dtype)

# Kernel to create a tensor filled with zeros like another tensor
@triton.jit
def zeros_like(input):
    return zeros(input.shape, input.dtype)

