import triton

@triton.jit
def _argmax_combine_tie_break_left(value1, index1, value2, index2):
    tie = value1 == value2 and index1 < index2
    gt = value1 > value2 or tie
    v_ret = triton.language.where(gt, value1, value2)
    i_ret = triton.language.where(gt, index1, index2)
    return v_ret, i_ret

@triton.jit
def _argmax_combine_tie_break_fast(value1, index1, value2, index2):
    tie = False
    gt = value1 > value2 or tie
    v_ret = triton.language.where(gt, value1, value2)
    i_ret = triton.language.where(gt, index1, index2)
    return v_ret, i_ret

@triton.jit
def _fast_max(x, y):
    return triton.language.math.max(x, y)

@triton.jit
def max(input, axis=None, return_indices=False, return_indices_tie_break_left=True):
    input = triton.language._promote_reduction_input(input)
    if return_indices:
        if return_indices_tie_break_left:
            return triton.language._reduce_with_indices(input, axis, _argmax_combine_tie_break_left)
        else:
            return triton.language._reduce_with_indices(input, axis, _argmax_combine_tie_break_fast)
    else:
        if triton.language.constexpr(input.dtype.primitive_bitwidth) < 32:
            if triton.language.constexpr(input.dtype.is_floating()):
                input = input.to(triton.language.float32)
            else:
                assert input.dtype.is_integer_type()
                input = input.to(triton.language.int32)
        return triton.language.reduce(input, axis, _fast_max)

@triton.jit
def argmax(input, axis, tie_break_left=True):
    (_, ret) = max(input, axis, return_indices=True, return_indices_tie_break_left=tie_break_left)
    return ret

