def heur_tile_k(args):
    tile_k = 1
    MAX_TILE_K = 8192
    NUM_SMS = torch.cuda.get_device_properties(torch.cuda.current_device()).multi_processor_count
    upper_bound = min(args["K"], MAX_TILE_K)
    while tile_k <= upper_bound:
