def _layer_norm_fwd(
    x, weight, bias, eps, residual=None, x1=None, weight1=None, bias1=None, dropout_p=0.0,
    rowscale=None, out_dtype=None, residual_dtype=None, is_rms_norm=False, return_dropout_mask=False,
):
    M, N = x.shape
    y = torch.empty_like(x, dtype=x.dtype if out_dtype is None else out_dtype)
    mean = torch.empty((M,), dtype=torch.float32, device=x.device) if not is_rms_norm else None
    rstd = torch.empty((M,), dtype=torch.float32, device=x.device)
    if dropout_p > 0.0:
        seeds = torch.randint(2**32, (M if x1 is None else 2 * M,), device=x.device, dtype=torch.int64)
    else:
        seeds = None
    if return_dropout_mask and dropout_p > 0.0:
        dropout_mask = torch.empty(M if x1 is None else 2 * M, N, device=x.device, dtype=torch.bool)
    else:
        dropout_mask = None
    BLOCK_N = min(65536 // x.element_size(), triton.next_power_of_2(N))
    with torch.cuda.device(x.device.index):
        _layer_norm_fwd_1pass_kernel[(M,)](
            x, y, weight, bias, residual, x1, weight1, bias1, None, None, rowscale, seeds,
            dropout_mask, mean, rstd, x.stride(0), y.stride(0), 0, 0, 0, 0, M, N, eps, dropout_p,
            is_rms_norm, BLOCK_N, residual is not None, None, bias is not None, dropout_p > 0.0,
            dropout_mask is not None, rowscale is not None,
        )
    return (y, None, mean, rstd, None, seeds, dropout_mask, None)


@triton.autotune(
    configs=[
        triton.Config({}, num_warps=1),
        triton.Config({}, num_warps=2),
        triton.Config({}, num_warps=4),
        triton.Config({}, num_warps=8),
        triton.Config({}, num_warps=16),
        triton.Config({}, num_warps=32),
    ],
    key=["N", "HAS_DRESIDUAL", "STORE_DRESIDUAL", "IS_RMS_NORM", "HAS_BIAS", "HAS_DROPOUT"],
)
@triton.heuristics({"HAS_ROWSCALE": lambda args: args["ROWSCALE"] is not None})
@triton.heuristics({"HAS_DY1": lambda args: args["DY1"] is not None})
@triton.heuristics({"HAS_DX1": lambda args: args["DX1"] is not None})
@triton.heuristics({"HAS_B1": lambda args: args["DB1"] is not None})
@triton.heuristics({"RECOMPUTE_OUTPUT": lambda args: args["Y"] is not None})
@triton.jit
def _layer_norm_bwd_kernel(
    X, W, B, Y, DY, DX, DW, DB, DRESIDUAL, W1, DY1, DX1, DW1, DB1, DRESIDUAL_IN, ROWSCALE, SEEDS,
    Mean, Rstd, stride_x_row, stride_y_row, stride_dy_row, stride_dx_row, stride_dres_row,
    stride_dy1_row, stride_dx1_row, stride_dres_in_row,
    M, N, eps, dropout_p, rows_per_program,
    IS_RMS_NORM: tl.constexpr, BLOCK_N: tl.constexpr, HAS_DRESIDUAL: tl.constexpr,
    STORE_DRESIDUAL: tl.constexpr, HAS_BIAS: tl.constexpr, HAS_DROPOUT: tl.constexpr,
    HAS_ROWSCALE: tl.constexpr, HAS_DY1: tl.constexpr, HAS_DX1: tl.constexpr,
    HAS_B1: tl.constexpr, RECOMPUTE_OUTPUT: tl.constexpr,
):
    # Triton kernel logic...

def _layer_norm_bwd(
    dy, x, weight, bias, eps, mean, rstd, dresidual=None, dy1=None, weight1=None, bias1=None,
    seeds=None, dropout_p=0.0, rowscale=None, has_residual=False, has_x1=False,
    is_rms_norm=False, x_dtype=None, recompute_output=False,
):
    M, N = x.shape
    dx = (
        torch.empty_like(x)
        if x_dtype is None
        else torch.empty(M, N, dtype=x_dtype, device=x.device)
    )
    BLOCK_N = min(65536 // x.element_size(), triton.next_power_of_2(N))
    sm_count = torch.cuda.get_device_properties(x.device).multi_processor_count
    _dw = torch.empty((sm_count, N), dtype=torch.float32, device=weight.device)
    _db = (
        torch.empty((sm_count, N), dtype=torch.float32, device=bias.device)
        if bias is not None
        else None
    )
    with torch.cuda.device(x.device.index):
        _layer_norm_bwd_kernel[sm_count](
            x, weight, bias, None, dy, dx, _dw, _db, dresidual, weight1, dy1, None, None, None,
            None, rowscale, seeds, mean, rstd, x.stride(0), 0, dy.stride(0), dx.stride(0), 0, 0, 0, 0,
            M, N, eps, dropout_p, math.ceil(M / sm_count),
            is_rms_norm, BLOCK_N, dresidual is not None, None, bias is not None, dropout_p > 0.0,
        )
    dw = _dw.sum(0).to(weight.dtype)
    db = _db.sum(0).to(bias.dtype) if bias is not None else None
    return (dx, dw, db, None, None, None, None)


class LayerNormFn(torch.autograd.Function):
    @staticmethod
    def forward(ctx, x, weight, bias, residual=None, x1=None, weight1=None, bias1=None, eps=1e-6,
                dropout_p=0.0, rowscale=None, prenorm=False, residual_in_fp32=False,
                is_rms_norm=False, return_dropout_mask=False):
        x_shape_og = x.shape
        x = x.reshape(-1, x.shape[-1])
        weight = weight.contiguous()
        ctx.save_for_backward(None, weight, bias, weight1, bias1, rowscale, None, None, None)
        ctx.x_shape_og = x_shape_og
        ctx.eps = eps
        ctx.dropout_p = dropout_p
        ctx.is_rms_norm = is_rms_norm
        ctx.has_residual = residual is not None
        ctx.has_x1 = x1 is not None
        ctx.prenorm = prenorm
        ctx.x_dtype = x.dtype
        y = y.reshape(x_shape_og)
        return (y, None, None) if not prenorm else (y, None, None)

    @staticmethod
    def backward(ctx, dy, *args):
        x, weight, bias, weight1, bias1, rowscale, seeds, mean, rstd = ctx.saved_tensors
        dy = dy.reshape(-1, dy.shape[-1])
        dx, dw, db, dresidual_in, dx1, dw1, db1 = _layer_norm_bwd(
            dy, x, weight, bias, ctx.eps, mean, rstd, None, None, weight1, bias1, None, ctx.dropout_p,
            rowscale, ctx.has_residual, ctx.has_x1, ctx.is_rms_norm, x_dtype=ctx.x_dtype,
        )
        return (
            dx.reshape(ctx.x_shape_og), dw, db, None, None, None, None, None, None, None, None, None, None, None
        )

def layer_norm_fn(
    x, weight, bias, residual=None, x1=None, weight1=None, bias1=None, eps=1e-6,
    dropout_p=0.0, rowscale=None, prenorm=False, residual_in_fp32=False,
    is_rms_norm=False, return_dropout_mask=False,
):
