import torch
import numpy as np
import time
import triton
import triton.language as tl
from triton.runtime.jit import reinterpret

uint_dtypes = ["uint8", "uint16", "uint32", "uint64"]

def to_triton(x: np.ndarray, device="cuda", dst_type=None):
    t = x.dtype.name
    if t in uint_dtypes:
        signed_type_name = t.lstrip("u")
        x_signed = x.astype(getattr(np, signed_type_name))
        return reinterpret(
            torch.tensor(x_signed, device=device).contiguous(), getattr(tl, t)
        )
    else:
        return torch.tensor(x, device=device).contiguous()

def to_numpy(x):
    if isinstance(x, torch.Tensor):
        if x.dtype is torch.bfloat16:
            return x.cpu().float().numpy()
        return x.cpu().numpy()
    else:
        raise ValueError(f"Not a triton-compatible tensor: {x}")

@triton.jit
def sum_op(a, b):
    return a + b

@triton.jit
def kernel(X, Z, BLOCK_M: tl.constexpr, BLOCK_N: tl.constexpr, AXIS: tl.constexpr):
    range_m = tl.arange(0, BLOCK_M)
    range_n = tl.arange(0, BLOCK_N)
    x = tl.load(X + range_m[:, None] * BLOCK_N + range_n[None, :])
    z = tl.associative_scan(x, 0, sum_op)
    tl.store(Z + range_m[:, None] * BLOCK_N + range_n[None, :], z)

