# Kernel to floor a value
@triton.jit
def _floor(x):
    return x - x % 1


# Kernel to round a value
@triton.jit
def _round(x):
    return _floor(x + 0.5)


# Kernel to check if coordinates are in bounds
@triton.jit
def is_in_bounds(
    x, y, z, C: tl.constexpr, BLOCK_SIZE: tl.constexpr
):
    in_bounds = (tl.abs(x) <= 1) * (tl.abs(y) <= 1) * (tl.abs(z) <= 1)
    if C == 1:
        in_bounds_mask = tl.view(in_bounds.to(tl.float32), (BLOCK_SIZE,))
    else:
        in_bounds_mask = tl.broadcast_to(
            in_bounds.to(tl.float32)[:, None], (BLOCK_SIZE, C)
        )
    return in_bounds_mask


# Kernel to splat in 3D
@triton.jit
def _splat_3d(
    to_splat, grad_image, w, batch_index, ix, iy, iz, ID, IH, IW,
    C: tl.constexpr, BLOCK_SIZE: tl.constexpr
):
    Coffs = tl.arange(0, C)
    ix_ = tl.minimum(tl.maximum(ix, 0.0), IW - 1).to(tl.int32)
    iy_ = tl.minimum(tl.maximum(iy, 0.0), IH - 1).to(tl.int32)
    iz_ = tl.minimum(tl.maximum(iz, 0.0), ID - 1).to(tl.int32)

    w = w * ((iy >= 0) * (iy < IH) * (ix >= 0) * (ix < IW) * (iz < ID) * (iz >= 0)).to(tl.float32)

    w = tl.view(w[:, None], (BLOCK_SIZE, 1))
    offs = tl.view(
        (batch_index * ID * IW * IH * C + iz_ * IW * IH * C + iy_ * IW * C + ix_ * C)[:, None] + Coffs[None, :],
        (BLOCK_SIZE, C)
    )
    tl.atomic_add(grad_image + offs, w * to_splat)


# Kernel to splat in 2D
@triton.jit
def _splat_2d(
    to_splat, grad_image, w, batch_index, ix, iy, IH, IW,
    C: tl.constexpr, BLOCK_SIZE: tl.constexpr
):
    Coffs = tl.arange(0, C)
    ix_ = tl.minimum(tl.maximum(ix, 0.0), IW - 1).to(tl.int32)
    iy_ = tl.minimum(tl.maximum(iy, 0.0), IH - 1).to(tl.int32)

    w = w * ((iy >= 0) * (iy < IH) * (ix >= 0) * (ix < IW)).to(tl.float32)

    w = tl.view(w[:, None], (BLOCK_SIZE, 1))
    offs = tl.view(
        (batch_index * IW * IH * C + iy_ * IW * C + ix_ * C)[:, None] + Coffs[None, :],
        (BLOCK_SIZE, C)
    )
    tl.atomic_add(grad_image + offs, w * to_splat)


# Kernel to sample in 3D
@triton.jit
def _sample_3d(
    image, w, batch_index, ix, iy, iz, ID, IH, IW,
    C: tl.constexpr, BLOCK_SIZE: tl.constexpr
):
    Coffs = tl.arange(0, C)
    ix_ = tl.minimum(tl.maximum(ix, 0.0), IW - 1).to(tl.int32)
    iy_ = tl.minimum(tl.maximum(iy, 0.0), IH - 1).to(tl.int32)
    iz_ = tl.minimum(tl.maximum(iz, 0.0), ID - 1).to(tl.int32)

    image_offs = (
        image + batch_index * ID * IW * IH * C + iz_ * IW * IH * C + iy_ * IW * C + ix_ * C
    )

    mask_w = w * ((iy >= 0) * (iy < IH) * (ix >= 0) * (ix < IW) * (iz < ID) * (iz >= 0)).to(tl.float32)

    if C == 1:  # do not append the last dim
        val = tl.view(tl.load(image_offs).to(tl.float32), (BLOCK_SIZE,))
        out = tl.view(val * mask_w, (BLOCK_SIZE,))
        return out
    else:
        val = tl.view(
            tl.load(image_offs[:, None] + Coffs[None, :]).to(tl.float32), (BLOCK_SIZE, C)
        )
        mask_w_bcast = tl.view(mask_w[:, None], (BLOCK_SIZE, 1))
        return val * mask_w_bcast


# Kernel to sample in 2D
@triton.jit
def _sample_2d(
    image, w, batch_index, ix, iy, IH, IW,
    C: tl.constexpr, BLOCK_SIZE: tl.constexpr
):
    Coffs = tl.arange(0, C)
    ix_ = tl.minimum(tl.maximum(ix, 0.0), IW - 1).to(tl.int32)
    iy_ = tl.minimum(tl.maximum(iy, 0.0), IH - 1).to(tl.int32)

    image_offs = (
        image + batch_index * IW * IH * C + iy_ * IW * C + ix_ * C
    )

    mask_w = w * ((iy >= 0) * (iy < IH) * (ix >= 0) * (ix < IW)).to(tl.float32)

    if C == 1:  # do not append the last dim
        val = tl.view(tl.load(image_offs).to(tl.float32), (BLOCK_SIZE,))
        out = tl.view(val * mask_w, (BLOCK_SIZE,))
        return out
    else:
        val = tl.view(
            tl.load(image_offs[:, None] + Coffs[None, :]).to(tl.float32), (BLOCK_SIZE, C)
        )
        mask_w_bcast = tl.view(mask_w[:, None], (BLOCK_SIZE, 1))
        return val * mask_w_bcast

import triton
import triton.language as tl


@triton.jit
def contract_pi(x, y, z):
    # MERF contract_pi function
    n = tl.maximum(tl.maximum(tl.abs(x), tl.abs(y)), tl.abs(z))
    x_c = _contract_pi_one(x, n)
    y_c = _contract_pi_one(y, n)
    z_c = _contract_pi_one(z, n)
    return x_c, y_c, z_c


@triton.jit
def _contract_pi_one(x, n):
    x_c = tl.where(
        n <= 1.0,
        x,
        tl.where(
            tl.abs(tl.abs(x) - n) <= 1e-8, (2 - 1 / tl.abs(x)) * (x / tl.abs(x)), x / n
        ),
    )
    # important: we map the contracted coords from [-2, 2] to [-1, 1]!
    x_c = x_c * 0.5
    return x_c


@triton.jit
def depth_inv_sphere(far, disparity_at_inf, n, step):
    frac_step = (step + 1) / n
    n_disp = (disparity_at_inf - 1) * frac_step + 1
    return far * (1 / n_disp)


@triton.jit
def depth_lin(near, far, n, step):
    frac_step = step / (n - 1)
    return (far - near) * frac_step + near

import triton
