@triton.jit
def load_weight_2dim(ptr, dim_in, dim_out):
    offs = tl.arange(0, dim_in)[:, None] * dim_out + tl.arange(0, dim_out)[None, :]
    w = tl.view(tl.load(ptr + offs), (dim_in, dim_out))
    return w

@triton.jit
def load_weight_last_opacity(ptr, dim_in, BLOCK_SIZE):
    offs = tl.zeros((BLOCK_SIZE, 1), dtype=tl.int32) + tl.arange(0, dim_in)[None, :]
    w = tl.view(tl.load(ptr + offs), (BLOCK_SIZE, dim_in))
    return w

@triton.jit
def load_bias_last_opacity(ptr, BLOCK_SIZE):
    return tl.view(tl.load(ptr + tl.zeros((BLOCK_SIZE,), dtype=tl.int32)), (BLOCK_SIZE,))

@triton.jit
def load_weight(ptr, dim_in, dim_out):
    return load_weight_2dim(ptr, dim_in, dim_out)

@triton.jit
def load_bias(ptr, dim, BLOCK_SIZE):
    return tl.view(tl.load((ptr + tl.arange(0, dim))[None, :] + tl.zeros((BLOCK_SIZE, 1), dtype=tl.int32)), (BLOCK_SIZE, dim))

@triton.jit
def update_weight(ptr, dim_in, dim_out, grad):
    offs = tl.arange(0, dim_in)[:, None] * dim_out + tl.arange(0, dim_out)[None, :]
    tl.atomic_add(ptr + offs, grad)

@triton.jit
def update_bias(ptr, dim, grad):
    offs = tl.arange(0, dim)
    tl.atomic_add(ptr + offs, grad)

@triton.jit
def load_mlp_params_opacity(mlp_params, DIM_IN, DIM_HIDDEN, DIM_OUT, BLOCK_SIZE):
    prev_offs = "0"
    for load_weight in [True, False]:
        dim_in = "DIM_IN"
        for l in range(int(N_LAYERS_OPACITY)):  # load weights
            dim_out = f"DIM_OUT" if (l == int(N_LAYERS_OPACITY) - 1) else f"DIM_HIDDEN"
            if load_weight:
                w_offs = f"{prev_offs}"
                w_numel = f"{dim_in} * {dim_out}"
                if l==int(N_LAYERS_OPACITY)-1:
                    w = load_weight_last_opacity(mlp_params + w_offs, dim_in, BLOCK_SIZE)
                else:
                    w = load_weight(mlp_params + w_offs, dim_in, dim_out)
                prev_offs = f"{w_offs} + {w_numel}"
            else:
                b_offs = f"{prev_offs}"
                b_numel = f"{dim_out}"
                if l==int(N_LAYERS_OPACITY)-1:
                    b = load_bias_last_opacity(mlp_params + b_offs, BLOCK_SIZE)
                else:
                    b = load_bias(mlp_params + b_offs, dim_out, BLOCK_SIZE)
                prev_offs = f"{b_offs} + {b_numel}"
            dim_in = dim_out
    return prev_offs, None

@triton.jit
def mlp_opacity(x, w0, b0):
    for l in range(N_LAYERS_OPACITY):
        if l == int(N_LAYERS_OPACITY) - 1:
             x = tl.sum(x * w0, axis=1) + tl.ravel(b0)
        else:
            x = tl.dot(x, w0, allow_tf32=ALLOW_TF32) + b0
        if l < int(N_LAYERS_OPACITY) - 1:
            x = tl.maximum(x, 0.0)
    return x

@triton.jit
def mlp_opacity_with_inter_feat(x, w0, b0):
    inter_x = ""
    inter_xwb = ""
    for l in range(N_LAYERS_OPACITY):
        xl = x
        inter_x = inter_x + f", x{l}"
        if l == int(N_LAYERS_OPACITY) - 1:
             x = tl.sum(x * w0, axis=1)
             x = x + tl.ravel(b0)
        else:
            x = tl.dot(x, w0, allow_tf32=ALLOW_TF32) + b0
        if l < int(N_LAYERS_OPACITY) - 1:
            xwb = x
            inter_xwb = inter_xwb + f", xwb{l}"
            x = tl.maximum(x, 0.0)
    return x + inter_x + inter_xwb

@triton.jit
def _d_inner_product(d_y, w, b, x):
    d_w = tl.sum(x * d_y, axis=0)
    d_b = tl.sum(d_y, axis=0)
    d_x = w * d_y
    return d_x, d_w, d_b

@triton.jit
def d_mlp_opacity(dy, w0, b0, x0):
    for l in reversed(range(N_LAYERS_OPACITY)):
        if l == int(N_LAYERS_OPACITY) - 1:
            dy, dw0_opacity, db0_opacity = _d_inner_product(dy, w0, b0, x0)
        elif l < int(N_LAYERS_OPACITY) - 1:
            dy, dw0_opacity, db0_opacity = _d_linear_relu(dy, w0, b0, None, x0)
        else:
            dy, dw0_opacity, db0_opacity = _d_linear(dy, w0, b0, x0)
    return dy, None

