            dim_out = f"DIM_OUT" if (l == int(N_LAYERS_OPACITY) - 1) else f"DIM_HIDDEN"
            if load_weight:
                w_offs = f"{prev_offs}"
                w_numel = f"{dim_in} * {dim_out}"
                if l == int(N_LAYERS_OPACITY) - 1:
                    update_weight(mlp_params + w_offs, 1, dim_in, dw0_opacity)
                else:
                    update_weight(mlp_params + w_offs, dim_in, dim_out, dw0_opacity)
