# Kernel to load MLP parameters
@triton.jit
def load_mlp_params(mlp_params, DIM_IN, DIM_HIDDEN, DIM_OUT, BLOCK_SIZE):
    prev_offs = 0
    for load_weight in [True, False]:
        dim_in = DIM_IN
        for l in range(N_LAYERS):  # load weights
            dim_out = DIM_OUT if l == N_LAYERS - 1 else DIM_HIDDEN
            if load_weight:
                w_offs = prev_offs
                w_numel = dim_in * dim_out
                w = load_weight(mlp_params + w_offs, dim_in, dim_out)
                prev_offs = w_offs + w_numel
            else:
                b_offs = prev_offs
                b_numel = dim_out
                b = load_bias(mlp_params + b_offs, dim_out, BLOCK_SIZE)
                prev_offs = b_offs + b_numel
            dim_in = dim_out
    return

@triton.jit
def _d_linear(d_y, w, b, x):
    # gradients of `y = x @ w + b`
    d_x = tl.dot(d_y, tl.trans(w), allow_tf32=ALLOW_TF32)
    d_w = tl.trans(tl.dot(tl.trans(d_y), x, allow_tf32=ALLOW_TF32))
    d_b = tl.sum(d_y, axis=0)
    return d_x, d_w, d_b

@triton.jit
def _d_linear_relu(d_y, w, b, xwb, x):
    # gradients of `y = max(x @ w + b, 0); xwb = x @ w + b`
    d_y_relu = d_y * (xwb > 0.0).to(tl.float32)
    return _d_linear(d_y_relu, w, b, x)

@triton.jit
def load_weight(ptr, dim_in, dim_out):
    return load_weight_2dim(ptr, dim_in, dim_out)

@triton.jit
def load_weight_2dim(ptr, dim_in, dim_out):
    offs = tl.arange(0, dim_in)[:, None] * dim_out + tl.arange(0, dim_out)[None, :]
    w = tl.view(tl.load(ptr + offs), (dim_in, dim_out))
    return w

@triton.jit
def load_bias(ptr, dim, BLOCK_SIZE):
    return tl.view(tl.load((ptr + tl.arange(0, dim))[None, :] + tl.zeros((BLOCK_SIZE, 1), dtype=tl.int32)), (BLOCK_SIZE, dim))

@triton.jit
def update_weight(ptr, dim_in, dim_out, grad):
    offs = tl.arange(0, dim_in)[:, None] * dim_out + tl.arange(0, dim_out)[None, :]
    tl.atomic_add(ptr + offs, grad)

@triton.jit
def update_bias(ptr, dim, grad):
    offs = tl.arange(0, dim)
    tl.atomic_add(ptr + offs, grad)

@triton.jit
def mlp_splatter(x):
    for l in range(N_LAYERS):
        x = tl.dot(x, w[l], allow_tf32=ALLOW_TF32) + b[l]
        if l < N_LAYERS - 1:
            x = tl.maximum(x, 0.0)
    return x

@triton.jit
def mlp_splatter_with_inter_feat(x):
    inter_x = ""
    inter_xwb = ""
    for l in range(N_LAYERS):
        x[l] = x
        inter_x = inter_x + f", x{l}"
        x = tl.dot(x, w[l], allow_tf32=ALLOW_TF32) + b[l]
        if l < N_LAYERS - 1:
            xwb[l] = x
            inter_xwb = inter_xwb + f", xwb{l}"
            x = tl.maximum(x, 0.0)
    return x, inter_x, inter_xwb

@triton.jit
def update_mlp_params(mlp_params, DIM_IN, DIM_HIDDEN, DIM_OUT, grads):
    prev_offs = 0
    for load_weight in [True, False]:
        dim_in = DIM_IN
        for l in range(N_LAYERS):  # load weights
            dim_out = DIM_OUT if l == N_LAYERS - 1 else DIM_HIDDEN
            if load_weight:
                w_offs = prev_offs
                w_numel = dim_in * dim_out
                update_weight(mlp_params + w_offs, dim_in, dim_out, grads[l])
                prev_offs = w_offs + w_numel
            else:
                b_offs = prev_offs
                b_numel = dim_out
                update_bias(mlp_params + b_offs, dim_out, grads[l])
                prev_offs = b_offs + b_numel
            dim_in = dim_out

@triton.jit
def d_mlp_splatter(dy, wb, xwb, x):
    for l in reversed(range(N_LAYERS)):
        if l < N_LAYERS - 1:
            dy, dw, db = _d_linear_relu(dy, w[l], b[l], xwb[l], x[l])
        else:
            dy, dw, db = _d_linear(dy, w[l], b[l], x[l])
    return dy, dw, db

@triton.jit
def init_mlp_params_grads(DIM_HIDDEN_mlp, DIM_IN_mlp, DIM_OUT_mlp):
    grads = []
    dim_in = DIM_IN_mlp
    for l in range(N_LAYERS):
        dim_out = DIM_OUT_mlp if l == N_LAYERS - 1 else DIM_HIDDEN_mlp
        grads.append(tl.zeros((dim_in, dim_out), dtype=tl.float32))
        grads.append(tl.zeros((dim_out,), dtype=tl.float32))
        dim_in = dim_out
    return grads

