# Kernel function to promote a value to a tensor
@triton.jit
def promote_to_tensor(x):
    # Addition promotes to tensor for us
    return x + tl.zeros((1,), tl.int1)

# Kernel function to check if a value is floating
@triton.jit
def is_floating(x):
    return promote_to_tensor(x).dtype.is_floating()

# Kernel function to accumulate product of two values
@triton.jit
def _prod_accumulate(a, b):
    return a * b

# Kernel function to compute product over an axis
@triton.jit
def prod(input, axis):
    return tl.reduce(input, axis, _prod_accumulate)

# Kernel function to compute the minimum of two values
@triton.jit
def minimum(a, b):
    mask = a < b
    if is_floating(a):
        mask |= a != a
    return tl.where(mask, a, b)

# Kernel function to compute the maximum of two values
@triton.jit
def maximum(a, b):
    mask = a > b
    if is_floating(a):
        mask |= a != a
    return tl.where(mask, a, b)

# Kernel function to compute the minimum over an axis
@triton.jit
def min2(a, dim):
    return tl.reduce(a, dim, minimum)

# Kernel function to compute the maximum over an axis
@triton.jit
def max2(a, dim):
    return tl.reduce(a, dim, maximum)

# Kernel function to compute minimum with index for two values
@triton.jit
def minimum_with_index(a_value, a_index, b_value, b_index):
    mask = a_value < b_value
    equal = a_value == b_value
    if is_floating(a_value):
        a_isnan = a_value != a_value
        b_isnan = b_value != b_value
        mask |= a_isnan and not b_isnan
        equal |= a_isnan and b_isnan

    mask |= equal & (a_index < b_index)
    return tl.where(mask, a_value, b_value), tl.where(mask, a_index, b_index)

# Kernel function to compute maximum with index for two values
@triton.jit
def maximum_with_index(a_value, a_index, b_value, b_index):
    mask = a_value > b_value
    equal = a_value == b_value
    if is_floating(a_value):
        a_isnan = a_value != a_value
        b_isnan = b_value != b_value
        mask |= a_isnan and not b_isnan
        equal |= a_isnan and b_isnan

    mask |= equal & (a_index < b_index)
    return tl.where(mask, a_value, b_value), tl.where(mask, a_index, b_index)

# Kernel function to perform reduction for Welford's algorithm
@triton.jit
def welford_reduce(value, mean, m2, weight):
    delta = value - mean
    new_weight = weight + 1
    new_mean = mean + delta / new_weight
    return new_mean, m2 + delta * (value - new_mean), new_weight

# Kernel function to combine results for Welford's algorithm
@triton.jit
def welford_combine(mean_1, m2_1, weight_1, mean_2, m2_2, weight_2):
    delta = mean_2 - mean_1
    new_weight = weight_1 + weight_2
    w2_over_w = tl.where(new_weight == 0.0, 0.0, weight_2 / new_weight)
    return mean_1 + delta * w2_over_w, m2_1 + m2_2 + delta * delta * weight_1 * w2_over_w, new_weight

# Kernel function to perform Welford's algorithm over an axis
@triton.jit
def welford(mean, m2, weight, dim):
    return tl.reduce((mean, m2, weight), dim, welford_combine)

# Kernel function to assert a condition on the device
@triton.jit
def device_assert_then(cond, msg, r):
    tl.device_assert(cond, msg)
    return r

# Kernel function to generate a 64-bit random integer
@triton.jit
def randint64(seed, offset, low, high):
    r0, r1, r2, r3 = tl.randint4x(seed, offset)
    r0 = r0.to(tl.uint64)
    r1 = r1.to(tl.uint64)
    result = r0 | (r1 << 32)
    size = high - low
    result = result % size.to(tl.uint64)
    result = result.to(tl.int64) + low
    return result

# Kernel function for any operation
@triton.jit
def any(a, dim):
    return tl.reduce(a, dim, _any_combine)

# Kernel function to perform binary search for bucketization
@triton.jit
def bucketize_binary_search(values, offsets_ptr, indexing_dtype, right, OFFSETS_SIZE, BLOCK_SHAPE):
    low = tl.zeros(BLOCK_SHAPE, dtype=indexing_dtype)
    high = tl.full(BLOCK_SHAPE, OFFSETS_SIZE, dtype=indexing_dtype)

    full_range = OFFSETS_SIZE + 1
    while full_range > 1:
        mid = (high + low) // 2
        mask = mid < OFFSETS_SIZE
        bucket_upper_bound = tl.load(offsets_ptr + mid, mask=mask)
        if right:
            is_above = values >= bucket_upper_bound
        else:
            is_above = values > bucket_upper_bound

        low = tl.where(is_above & mask, mid + 1, low)
        high = tl.where(is_above, high, mid)

        full_range = (full_range + 1) // 2

    return low

