import torch
import triton
import triton.language as tl

BLOCK: tl.constexpr = 1024

@triton.jit
def kernel(X, N, seed):
    pid = tl.program_id(0).to(X.dtype.element_ty)
    offset = pid * BLOCK + tl.arange(0, BLOCK)
    rand = tl.randint(seed, offset)
    tl.store(X + offset, rand, mask=offset < N)

@triton.jit
def const_kernel(X, N, seed: tl.constexpr):
    pid = tl.program_id(0).to(X.dtype.element_ty)
    offset = pid * BLOCK + tl.arange(0, BLOCK)
    rand = tl.randint(seed, offset)
    tl.store(X + offset, rand, mask=offset < N)

@triton.jit
def kernel_rand(X, N, seed, dtype: tl.constexpr):
    pid = tl.program_id(0).to(dtype)
    offset = pid * BLOCK + tl.arange(0, BLOCK)
    rand = tl.rand(seed, offset)
    tl.store(X + offset, rand, mask=offset < N)

@triton.jit
def const_kernel_rand(X, N, seed: tl.constexpr, dtype: tl.constexpr):
    pid = tl.program_id(0).to(dtype)
    offset = pid * BLOCK + tl.arange(0, BLOCK)
    rand = tl.rand(seed, offset)
    tl.store(X + offset, rand, mask=offset < N)

@triton.jit
def kernel_randn(X, N, seed, dtype: tl.constexpr):
    pid = tl.program_id(0).to(dtype)
    offset = pid * BLOCK + tl.arange(0, BLOCK)
    rand = tl.randn(seed, offset)
    tl.store(X + offset, rand, mask=offset < N)

@triton.jit
def const_kernel_randn(X, N, seed: tl.constexpr, dtype: tl.constexpr):
    pid = tl.program_id(0).to(dtype)
    offset = pid * BLOCK + tl.arange(0, BLOCK)
    rand = tl.randn(seed, offset)
    tl.store(X + offset, rand, mask=offset < N)

@triton.jit
def kernel_rand_limits(input, output, n: tl.constexpr):
    idx = tl.arange(0, n)
    x = tl.load(input + idx)
    y = tl.random.uint_to_uniform_float(x)
    tl.store(output + idx, y)

def run_randint(size, seed, device, dtype, const_seed):
    x = torch.empty(size, dtype=getattr(torch, dtype), device=device)
    N = x.numel()
    grid = (triton.cdiv(N, BLOCK), )
    if const_seed:
        const_kernel[grid](x, N, seed=seed)
    else:
        kernel[grid](x, N, seed)
    return x

def run_rand(size, seed, dtype, device, const_seed):
    x = torch.empty(size, dtype=torch.float32, device=device)
    N = x.numel()
    grid = (triton.cdiv(N, BLOCK), )
    if const_seed:
        const_kernel_rand[grid](x, N, seed=seed, dtype=getattr(tl, dtype))
    else:
        kernel_rand[grid](x, N, seed, dtype=getattr(tl, dtype))
    return x

def run_randn(size, seed, dtype, device, const_seed):
    x = torch.empty(size, dtype=torch.float32, device=device)
    N = x.numel()
    grid = (triton.cdiv(N, BLOCK), )
    if const_seed:
        const_kernel_randn[grid](x, N, seed=seed, dtype=getattr(tl, dtype))
    else:
        kernel_randn[grid](x, N, seed, dtype=getattr(tl, dtype))
    return x

def run_rand_limits(dtype, device):
    torch_dtype = getattr(torch, dtype)
    min_max_int = torch.tensor([
        torch.iinfo(torch_dtype).min,
        torch.iinfo(torch_dtype).max,
    ], dtype=torch_dtype, device=device)
    output = torch.empty(2, dtype=torch.float32, device=device)
    kernel_rand_limits[(1, )](min_max_int, output, 2)
    return output

