@triton.jit
def matmul_kernel(
        a_ptr, b_ptr, c_ptr,
        M, N, K,
        stride_am, stride_ak,
        stride_bk, stride_bn,
        stride_cm, stride_cn,
        BLOCK_SIZE_M: tl.constexpr, BLOCK_SIZE_N: tl.constexpr, BLOCK_SIZE_K: tl.constexpr,
        GROUP_SIZE_M: tl.constexpr,
        ACTIVATION: tl.constexpr):
    pid = tl.program_id(axis=0)
    num_pid_m = tl.cdiv(M, BLOCK_SIZE_M)
    num_pid_n = tl.cdiv(N, BLOCK_SIZE_N)
    num_pid_in_group = GROUP_SIZE_M * num_pid_n
    group_id = pid // num_pid_in_group
    first_pid_m = group_id * GROUP_SIZE_M
    group_size_m = min(num_pid_m - first_pid_m, GROUP_SIZE_M)
    pid_m = first_pid_m + ((pid % num_pid_in_group) % group_size_m)
    pid_n = (pid % num_pid_in_group) // group_size_m
    offs_am = (pid_m * BLOCK_SIZE_M + tl.arange(0, BLOCK_SIZE_M)) % M
    offs_bn = (pid_n * BLOCK_SIZE_N + tl.arange(0, BLOCK_SIZE_N)) % N
    offs_k = tl.arange(0, BLOCK_SIZE_K)
    a_ptrs = a_ptr + (offs_am[:, None] * stride_am + offs_k[None, :] * stride_ak)
    b_ptrs = b_ptr + (offs_k[:, None] * stride_bk + offs_bn[None, :] * stride_bn)
    accumulator = tl.zeros((BLOCK_SIZE_M, BLOCK_SIZE_N), dtype=tl.float32)
    for k in range(0, tl.cdiv(K, BLOCK_SIZE_K)):
        a = tl.load(a_ptrs, mask=offs_k[None, :] < K - k * BLOCK_SIZE_K, other=0.0)
        b = tl.load(b_ptrs, mask=offs_k[:, None] < K - k * BLOCK_SIZE_K, other=0.0)
        accumulator = tl.dot(a, b, accumulator,  allow_tf32=False)
        a_ptrs += BLOCK_SIZE_K * stride_ak
        b_ptrs += BLOCK_SIZE_K * stride_bk
    c = accumulator
    offs_cm = pid_m * BLOCK_SIZE_M + tl.arange(0, BLOCK_SIZE_M)
    offs_cn = pid_n * BLOCK_SIZE_N + tl.arange(0, BLOCK_SIZE_N)
    c_ptrs = c_ptr + stride_cm * offs_cm[:, None] + stride_cn * offs_cn[None, :]
    c_mask = (offs_cm[:, None] < M) & (offs_cn[None, :] < N)
    tl.store(c_ptrs, c, mask=c_mask)

@triton.jit
def sum_kernel(x_ptr, output_ptr, M, N, BLOCK_M: tl.constexpr, BLOCK_N: tl.constexpr):
    pid_m = tl.program_id(axis=0)
    m_offset = pid_m * BLOCK_M + tl.arange(0, BLOCK_M)
    m_mask = m_offset < M  
    out = tl.zeros((BLOCK_M,), dtype=tl.float32) 
    for start in range(0, N, BLOCK_N):
        n_offset = start + tl.arange(0, BLOCK_N)
        offset = m_offset[:, None] * N + n_offset[None, :]
        n_mask = n_offset < N  
        mask = m_mask[:, None] & n_mask[None, :]  
        inp = tl.load(x_ptr + offset, mask=mask, other=0)
        out += tl.sum(inp, axis=1)

    tl.store(output_ptr + m_offset, out, mask=m_mask)

@triton.jit
def max_kernel(x_ptr, output_ptr, M, N, BLOCK_M: tl.constexpr, BLOCK_N: tl.constexpr):
    pid_m = tl.program_id(axis=0)
    m_offset = pid_m * BLOCK_M + tl.arange(0, BLOCK_M)
    m_mask = m_offset < M  
    out = tl.full((BLOCK_M,), -float('inf'), dtype=tl.float32)

    for start in range(0, N, BLOCK_N):
        n_offset = start + tl.arange(0, BLOCK_N)
        offset = m_offset[:, None] * N + n_offset[None, :]
        n_mask = n_offset < N  
        mask = m_mask[:, None] & n_mask[None, :]  
        inp = tl.load(x_ptr + offset, mask=mask, other=-float('inf'))
        out = tl.maximum(out, tl.max(inp, axis=1))

    tl.store(output_ptr + m_offset, out, mask=m_mask)

class NDArray:
    def __init__(self, data, device=None, dtype=None):
        if isinstance(data, np.ndarray):
            self.data = torch.from_numpy(data)
            self.data = self.data.cuda()
            self._device = device
        elif isinstance(data, NDArray):
            self.data = data.data
            self._device = data.device
        elif isinstance(data, torch.Tensor):
            self.data = data
            self._device = device
        else:
            self.data = torch.from_numpy(np.array(data))
            self._device = device

    @staticmethod
    def make(shape, device=None):
        data = torch.empty(shape, device=torch.device("cuda"), dtype=torch.float32)
        return NDArray(data, device=device)

    def compact(self):
        return NDArray(self.data.contiguous())

    def fill(self, value):
        self.data.fill_(value)

    def __repr__(self):
        return "NDArray:" + self.data.__repr__()

    def __str__(self):
        return self.__repr__()

    def numpy(self):
        return self.data.cpu().numpy()

    def to_numpy(self):
        return self.data.copy_to_host()

    @property
    def dtype(self):
        return self.data.dtype

    @property
    def shape(self):
        return self.data.shape

    @property
    def stride(self):
        return self.data.stride()

    def stride(self, dim):
        return self.data.stride(dim)

    @property
    def device(self):
        return self._device

    @property
    def size(self):
        return prod(self.shape)

    def triu(self, k=0):
        return NDArray(torch.triu(self.data, diagonal=k))

    @property
    def flat(self):
        out_tensor = NDArray(self.data.reshape((self.size,)))
        return out_tensor

    def __add__(self, y):
        output = torch.empty_like(self.data, device=torch.device("cuda"), dtype=self.dtype)
        assert self.data.is_cuda and output.is_cuda
        if self.data.is_contiguous() is False:
            self.data = self.data.contiguous()
        n_elements = output.numel()
        grid = lambda meta: (triton.cdiv(n_elements, meta["BLOCK_SIZE"]), )
        if isinstance(y, NDArray):
            if y.data.is_contiguous() is False:
                y.data = y.data.contiguous()
            add_kernel[grid](self.data, y.data, output.data, n_elements, BLOCK_SIZE=1024)
        else:
            add_scalar_kernel[grid](self.data, y, output.data, n_elements, BLOCK_SIZE=1024)
        return NDArray(output)

    __radd__ = __add__

    def __mul__(self, y):
        output = torch.empty_like(self.data, device=torch.device("cuda"), dtype=self.dtype)
        assert self.data.is_cuda and output.is_cuda
        if self.data.is_contiguous() is False:
            self.data = self.data.contiguous()
        n_elements = output.numel()
        grid = lambda meta: (triton.cdiv(n_elements, meta["BLOCK_SIZE"]), 1, 1)
        if isinstance(y, NDArray):
            if y.data.is_contiguous() is False:
                y.data = y.data.contiguous()
            mul_kernel[grid](self.data, y.data, output, n_elements, BLOCK_SIZE=1024)
        else:
            mul_scalar_kernel[grid](self.data, y, output, n_elements, BLOCK_SIZE=1024)
        return NDArray(output)

    __rmul__ = __mul__

    def __truediv__(self, y):
        output = torch.empty_like(self.data, dtype=self.dtype)
        assert self.data.is_cuda and output.is_cuda
        if self.data.is_contiguous() is False:
            self.data = self.data.contiguous()
        n_elements = output.numel()
        grid = lambda meta: (triton.cdiv(n_elements, meta["BLOCK_SIZE"]), )
        if isinstance(y, NDArray):
            if y.data.is_contiguous() is False:
                y.data = y.data.contiguous()
            div_kernel[grid](self.data, y.data, output, n_elements, BLOCK_SIZE=1024)
        else:
            div_scalar_kernel[grid](self.data, y, output, n_elements, BLOCK_SIZE=1024)
        return NDArray(output)

    def maximum(self, y):
        output = torch.zeros(self.shape, device=torch.device("cuda"), dtype=self.dtype)
        assert self.data.is_cuda and output.is_cuda
        if self.data.is_contiguous() is False:
            self.data = self.data.contiguous()
        n_elements = output.numel()
        grid = lambda meta: (triton.cdiv(n_elements, meta["BLOCK_SIZE"]), 1, 1)
        if isinstance(y, NDArray):
            if y.data.is_contiguous() is False:
                y.data = y.data.contiguous()
            maximum_kernel[grid](self.data, y.data, output, n_elements, BLOCK_SIZE=1024)
        else:
            maximum_scalar_kernel[grid](self.data, y, output, n_elements, BLOCK_SIZE=1024)
        return NDArray(output)

    def __neg__(self):
        if self.data.is_contiguous() is False:
            self.data = self.data.contiguous()
        return self * (-1)

    def __sub__(self, other):
        if self.data.is_contiguous() is False:
            self.data = self.data.contiguous()
        if other.data.is_contiguous() is False:
            other.data = other.data.contiguous()
        return self + (-other)

    def __rsub__(self, other):
        if self.data.is_contiguous() is False:
            self.data = self.data.contiguous()
        if isinstance(other, NDArray):
            if other.data.is_contiguous() is False:
                other.data = other.data.contiguous()
        return other + (-self)

    def log(self):
        output = torch.empty_like(self.data, dtype=self.dtype)
        assert self.data.is_cuda and output.is_cuda
        if self.data.is_contiguous() is False:
            self.data = self.data.contiguous()
        n_elements = output.numel()
        grid = lambda meta: (triton.cdiv(n_elements, meta["BLOCK_SIZE"]), )
        log_kernel[grid](self.data, output, n_elements, BLOCK_SIZE=1024)
        return NDArray(output)

    def exp(self):
        output = torch.empty_like(self.data, dtype=self.dtype)
        assert self.data.is_cuda and output.is_cuda
        if self.data.is_contiguous() is False:
            self.data = self.data.contiguous()
        n_elements = output.numel()
        grid = lambda meta: (triton.cdiv(n_elements, meta["BLOCK_SIZE"]), )
        exp_kernel[grid](self.data, output, n_elements, BLOCK_SIZE=1024)
        return NDArray(output)

    def cos(self):
        output = torch.empty_like(self.data, dtype=self.dtype)
        assert self.data.is_cuda and output.is_cuda
        if self.data.is_contiguous() is False:
            self.data = self.data.contiguous()
        n_elements = output.numel()
        grid = lambda meta: (triton.cdiv(n_elements, meta["BLOCK_SIZE"]), )
        cos_kernel[grid](self.data, output, n_elements, BLOCK_SIZE=1024)
        return NDArray(output)

    def sin(self):
        output = torch.empty_like(self.data, dtype=self.dtype)
        assert self.data.is_cuda and output.is_cuda
        if self.data.is_contiguous() is False:
            self.data = self.data.contiguous()
        n_elements = output.numel()
        grid = lambda meta: (triton.cdiv(n_elements, meta["BLOCK_SIZE"]), )
        sin_kernel[grid](self.data, output, n_elements, BLOCK_SIZE=1024)
        return NDArray(output)

    def sqrt(self):
        output = torch.empty_like(self.data, dtype=self.dtype)
        assert self.data.is_cuda and output.is_cuda
        if self.data.is_contiguous() is False:
            self.data = self.data.contiguous()
        n_elements = output.numel()
        grid = lambda meta: (triton.cdiv(n_elements, meta["BLOCK_SIZE"]), )
        sqrt_kernel[grid](self.data, output, n_elements, BLOCK_SIZE=1024)
        return NDArray(output)

    def __matmul__(self, b, activation=""):
        assert self.shape[-1] == b.shape[-2], "Incompatible dimensions"
        if self.data.is_contiguous() is False:
            self.data = self.data.contiguous()
        if b.data.is_contiguous() is False:
            b.data = b.data.contiguous()
        if len(self.shape) == 2:
            M, K = self.shape
            K, N = b.shape
            c = torch.empty((M, N), device=torch.device("cuda"), dtype=self.dtype)
            grid = lambda META: (triton.cdiv(M, META['BLOCK_SIZE_M']) * triton.cdiv(N, META['BLOCK_SIZE_N']), )
            matmul_kernel[grid](
                    self.data, b.data, c,
                    M, N, K,
                    self.stride(0), self.stride(1),
                    b.stride(0), b.stride(1),
                    c.stride(0), c.stride(1),
                    BLOCK_SIZE_M=64,
                    BLOCK_SIZE_N=64,
                    BLOCK_SIZE_K=32,
                    GROUP_SIZE_M=8,
                    ACTIVATION=activation
            )
            return NDArray(c)
        elif len(self.shape) == 3 and len(self.shape) == 3:
            bz1, M, K = self.shape
            bz2, K, N = b.shape
            assert bz1 == bz2, "Batch sizes do not match!"
            c = torch.empty((bz1, M, N), device=self.data.device, dtype=self.dtype)
            grid = lambda META: (triton.cdiv(M, META['BLOCK_SIZE_M']) * triton.cdiv(N, META['BLOCK_SIZE_N']), )
            for i in range(bz1):
                matmul_kernel[grid](
                        self.data[i], b.data[i], c.data[i],
                        M, N, K,
                        self.stride(-2), self.stride(-1),
                        b.stride(-2), b.stride(-1),
                        c.stride(-2), c.stride(-1),
                        BLOCK_SIZE_M=64,
                        BLOCK_SIZE_N=64,
                        BLOCK_SIZE_K=32,
                        GROUP_SIZE_M=8,
                        ACTIVATION=activation
                )
            return NDArray(c)

    def sum(self, axis=None, keepdims=False):
        shape = self.shape
        ndim = len(shape)
        if self.data.is_contiguous() is False:
            self.data = self.data.contiguous()
        if axis is None:
            axis = tuple(range(ndim))
        elif isinstance(axis, int):
            axis = (axis,)
        else:
            axis = tuple(axis)

        axes_to_keep = tuple(i for i in range(ndim) if i not in axis)
        new_order = axes_to_keep + axis

        self = self.permute(new_order)

        new_shape = tuple(shape[i] for i in axes_to_keep) + tuple(shape[i] for i in axis)

        m = prod(new_shape[:len(axes_to_keep)])
        n = prod(new_shape[len(axes_to_keep):])
        self = self.reshape((m, n))

        output_shape = tuple(new_shape[i] for i in range(len(axes_to_keep)))
        if keepdims:
            output_shape = list(shape)
            for i in axis:
                output_shape[i] = 1
            output_shape = tuple(output_shape)
        output = torch.empty(output_shape, device=torch.device("cuda"), dtype=self.dtype)

        block_m = 4
        block_n = min(triton.next_power_of_2(n), 1024)
        grid = (triton.cdiv(m, block_m), 1, 1)

        sum_kernel[grid](self.data, output, m, n, block_m, block_n)
        return NDArray(output)

    def max(self, axis=None, keepdims=False):
        shape = self.shape
        ndim = len(shape)
        if self.data.is_contiguous() is False:
            self.data = self.data.contiguous()
        if axis is None:
            axis = tuple(range(ndim))
        elif isinstance(axis, int):
            axis = (axis,)
        else:
            axis = tuple(axis)

        axes_to_keep = tuple(i for i in range(ndim) if i not in axis)
        new_order = axes_to_keep + axis

        self = self.permute(new_order)

        new_shape = tuple(shape[i] for i in axes_to_keep) + tuple(shape[i] for i in axis)

        m = prod(new_shape[:len(axes_to_keep)])
        n = prod(new_shape[len(axes_to_keep):])
        self = self.reshape((m, n))

        output_shape = tuple(new_shape[i] for i in range(len(axes_to_keep)))
        if keepdims:
            output_shape = list(shape)
            for i in axis:
                output_shape[i] = 1
            output_shape = tuple(output_shape)
        output = torch.empty(output_shape, device=torch.device("cuda"), dtype=self.dtype)

        block_m = 4
        block_n = min(triton.next_power_of_2(n), 1024)
        grid = (triton.cdiv(m, block_m), 1, 1)

        max_kernel[grid](self.data, output, m, n, block_m, block_n)
        return NDArray(output)

import torch
import triton
import triton.language as tl

@triton.jit()
def kernel(x_ptr, y_ptr, out_ptr):
    pid = tl.program_id(axis=0)
    x = tl.load(x_ptr + pid)
    y = tl.load(y_ptr + pid)
    out = x + y
    tl.store(out_ptr + pid, out)

def test_xpu_backend(cmdopt):
    if cmdopt == "xpu":
        has_ipex = False
        try:
            import intel_extension_for_pytorch  # type: ignore # noqa: F401
            has_ipex = True if hasattr(torch, "xpu") else False
        except Exception:
            has_ipex = False

        if has_ipex:
            for _ in range(1000):
                x = torch.randn((65536, ), device="xpu", dtype=torch.float32)
                y = torch.randn((65536, ), device="xpu", dtype=torch.float32)
                z = torch.zeros((65536, ), device="xpu", dtype=torch.float32)
                kernel[(65536, )](x, y, z, num_warps=32)
                assert torch.all(x + y == z)

import torch
import triton
import triton.language as tl
from torch.testing import assert_close

def get_current_target_warp_size():
    return triton.runtime.driver.active.get_current_target()[2]

@triton.jit
def kernel_device_assert(X, Y, BLOCK: tl.constexpr):
    x = tl.load(X + tl.arange(0, BLOCK))
    tl.device_assert(x == 0, "x != 0")
    tl.store(Y + tl.arange(0, BLOCK), x)

@triton.jit
def kernel_assert_passes(X, Y, BLOCK: tl.constexpr):
    x = tl.load(X + tl.arange(0, BLOCK))
    # Trivial assert, should not be an error.
    tl.device_assert(0 == 0, "x != 0")
    tl.store(Y + tl.arange(0, BLOCK), x)

@triton.jit(debug=False)
def kernel_device_assert_no_debug(X, Y, BLOCK: tl.constexpr):
    x = tl.load(X + tl.arange(0, BLOCK))
    tl.device_assert(x == 0, "x != 0")
    tl.store(Y + tl.arange(0, BLOCK), x)

@triton.jit
def kernel_assert(X, Y, BLOCK: tl.constexpr):
    x = tl.load(X + tl.arange(0, BLOCK))
    assert x == 0, "x != 0"
    tl.store(Y + tl.arange(0, BLOCK), x)

@triton.jit
def kernel_static_assert(X, Y, BLOCK: tl.constexpr):
    x = tl.load(X + tl.arange(0, BLOCK))
    tl.static_assert(BLOCK == 128, "BLOCK != 128")
    tl.store(Y + tl.arange(0, BLOCK), x)

def test_assert(func: str):
    N = 128  # This value should match with test_print in test_subprocess.py.
    num_warps = N // get_current_target_warp_size()

    x = torch.arange(0, N, dtype=torch.int32, device='cuda')
    y = torch.zeros((N, ), dtype=x.dtype, device="cuda")
    if func == "device_assert":
        kernel_device_assert[(1, )](x, y, num_warps=num_warps, BLOCK=N)
    if func == "device_assert_passes":
        # Assert passes; no error.
        kernel_assert_passes[(1, )](x, y, num_warps=num_warps, BLOCK=N)
    elif func == "no_debug":
        # TRITON_DEBUG=1 can override the debug flag
        kernel_device_assert_no_debug[(1, )](x, y, num_warps=num_warps, BLOCK=N)
    elif func == "assert":
        kernel_assert[(1, )](x, y, num_warps=num_warps, BLOCK=N)
    elif func == "static_assert":
        kernel_static_assert[(1, )](x, y, num_warps=num_warps, BLOCK=N)
    elif func == "double_assert":
        kernel_device_assert[(1, )](x, y, num_warps=num_warps, BLOCK=N)
        kernel_assert_passes[(1, )](x, y, num_warps=num_warps, BLOCK=N)
    assert_close(y, x)

