import numpy as np
import torch
import triton
import triton.language as tl
import pytest
from numpy.random import RandomState

# Description of the Triton kernel and its function
@triton.jit
def kernel(Z, X, SIZE: tl.constexpr):
    off = tl.arange(0, SIZE)
    x = tl.load(X + off)
    z = x + 1  # An example operation to ensure computation
    tl.store(Z + off, z)

# Function to initialize data and launch the kernel
def test_unary_op(dtype_x, expr, device):
    SIZE = 128
    x = numpy_random(SIZE, dtype_str=dtype_x)
    z_ref = eval(expr)

    x_tri = to_triton(x, device=device, dst_type=dtype_x)
    z_tri = to_triton(np.empty_like(x), device=device, dst_type=dtype_x)
    kernel[(1, )](z_tri, x_tri, SIZE=SIZE, num_warps=4)
    np.testing.assert_allclose(z_ref, to_numpy(z_tri), rtol=0.01)

def to_triton(x: np.ndarray, device, dst_type=None) -> Union[torch.Tensor, tl.Tensor]:
    if x.dtype.name in ['uint8', 'uint16', 'uint32', 'uint64']:
        signed_type_name = x.dtype.name.lstrip('u')
        x_signed = x.astype(getattr(np, signed_type_name))
        return torch.tensor(x_signed, device=device).to(getattr(tl, x.dtype.name))
    return torch.tensor(x, device=device)

def to_numpy(x):
    return x.cpu().numpy()

def numpy_random(shape, dtype_str, low=None, high=None):
    rs = RandomState(seed=17)
    if dtype_str in ['uint8', 'uint16', 'uint32', 'uint64']:
        iinfo = np.iinfo(getattr(np, dtype_str))
        low = iinfo.min if low is None else max(low, iinfo.min)
        high = iinfo.max if high is None else min(high, iinfo.max)
        return rs.randint(low, high, shape, dtype=getattr(np, dtype_str))
    elif dtype_str in ['float16', 'float32', 'float64']:
        return rs.normal(0, 1, shape).astype(getattr(np, dtype_str))
    else:
        raise RuntimeError(f'Unknown dtype {dtype_str}')

# Example of a test call
@pytest.mark.parametrize("dtype_x", ['int32', 'float32'])
def test_unary(dtype_x, device):
    test_unary_op(dtype_x, 'x + 1', device)

