@requires_cuda
def test_inplace_triton_kernel_training():
    @triton.jit
    def sin_kernel(
        in_ptr0,
        out_ptr,
        n_elements,
        BLOCK_SIZE: "tl.constexpr",
    ):
        pid = tl.program_id(axis=0)
        block_start = pid * BLOCK_SIZE
        offsets = block_start + tl.arange(0, BLOCK_SIZE)
        mask = offsets < n_elements
        x = tl.load(in_ptr0 + offsets, mask=mask)
        output = tl.sin(x)
        tl.store(out_ptr + offsets, output, mask=mask)

    def sin_triton(x, out):
        n_elements = x.numel()
        sin_kernel[(n_elements,)](x, out, n_elements, BLOCK_SIZE=4)

    factory_op = torch.empty_like

    class MySin(torch.autograd.Function):
        @staticmethod
        def forward(ctx, x):
            out = factory_op(x)
            sin_triton(x, out)
            ctx.save_for_backward(out)
            return out

        @staticmethod
        def backward(ctx, grad):
            (saved,) = ctx.saved_tensors
            out = factory_op(grad)
            sin_triton(saved, out)
            return out

    def f(x):
        return MySin.apply(x)

    x = torch.randn(3, device="cuda", requires_grad=True)
    print(count_numel_train(f, x))

