# Promotes a scalar to a tensor by adding it to a zero tensor.
@triton.jit
def promote_to_tensor(x):
    return x + tl.zeros((1,), tl.int1)

# Checks if the input tensor is of a floating-point type.
@triton.jit
def is_floating(x):
    return promote_to_tensor(x).dtype.is_floating()

# Computes the product of two elements.
@triton.jit
def _prod_accumulate(a, b):
    return a * b

# Reduces a tensor by computing the product along a specified axis.
@triton.jit
def prod(input, axis):
    return tl.reduce(input, axis, _prod_accumulate)

# Computes the minimum of two elements, considering NaN values.
@triton.jit
def minimum(a, b):
    mask = a < b
    if is_floating(a):
        mask |= a != a
    return tl.where(mask, a, b)

# Computes the maximum of two elements, considering NaN values.
@triton.jit
def maximum(a, b):
    mask = a > b
    if is_floating(a):
        mask |= a != a
    return tl.where(mask, a, b)

# Reduces a tensor by computing the minimum along a specified axis.
@triton.jit
def min2(a, dim):
    return tl.reduce(a, dim, minimum)

# Reduces a tensor by computing the maximum along a specified axis.
@triton.jit
def max2(a, dim):
    return tl.reduce(a, dim, maximum)

# Computes the minimum of two values with their indices, considering NaN values.
@triton.jit
def minimum_with_index(a_value, a_index, b_value, b_index):
    mask = a_value < b_value
    equal = a_value == b_value
    if is_floating(a_value):
        a_isnan = a_value != a_value
        b_isnan = b_value != b_value
        mask |= a_isnan and not b_isnan
        equal |= a_isnan and b_isnan
    mask |= equal & (a_index < b_index)
    return tl.where(mask, a_value, b_value), tl.where(mask, a_index, b_index)

# Computes the maximum of two values with their indices, considering NaN values.
@triton.jit
def maximum_with_index(a_value, a_index, b_value, b_index):
    mask = a_value > b_value
    equal = a_value == b_value
    if is_floating(a_value):
        a_isnan = a_value != a_value
        b_isnan = b_value != b_value
        mask |= a_isnan and not b_isnan
        equal |= a_isnan and b_isnan
    mask |= equal & (a_index < b_index)
    return tl.where(mask, a_value, b_value), tl.where(mask, a_index, b_index)

# Reduces two tensors by computing the minimum values along with their indices.
@triton.jit
def min_with_index(value, index, dim):
    return tl.reduce((value, index), dim, minimum_with_index)

# Reduces two tensors by computing the maximum values along with their indices.
@triton.jit
def max_with_index(value, index, dim):
    return tl.reduce((value, index), dim, maximum_with_index)

# Performs Welford's algorithm for online variance and mean calculation.
@triton.jit
def welford_reduce(value, mean, m2, weight, first_iteration):
    if first_iteration:
        new_weight = tl.full(weight.shape, 1, weight.dtype)
        new_mean = value
        new_m2 = tl.zeros_like(m2)
    else:
        delta = value - mean
        new_weight = weight + 1
        new_mean = mean + delta / new_weight
        new_m2 = m2 + delta * (value - new_mean)
    return new_mean, new_m2, new_weight

# Combines two sets of Welford values.
@triton.jit
def welford_combine(mean_1, m2_1, weight_1, mean_2, m2_2, weight_2):
    delta = mean_2 - mean_1
    new_weight = weight_1 + weight_2
    w2_over_w = tl.where(new_weight == 0.0, 0.0, weight_2 / new_weight)
    return (
        mean_1 + delta * w2_over_w,
        m2_1 + m2_2 + delta * delta * weight_1 * w2_over_w,
        new_weight,
    )

# Performs Welford reduction for online variance and mean calculation along a given dimension.
@triton.jit
def welford(mean, m2, weight, dim):
    return tl.reduce((mean, m2, weight), dim, welford_combine)

