# Triton kernel for tanh forward computation
@triton.jit
def tanh_triton_fwd(x):
    return 2 * tl.sigmoid(2 * x) - 1

# Triton kernel for tanh backward computation
@triton.jit
def tanh_triton_bwd(x):
    a = tanh_triton_fwd(x)
    return 1 - a * a

# Triton kernel for sigmoid forward computation
@triton.jit
def sigmoid_triton_fwd(x):
    return tl.sigmoid(x)

# Triton kernel for sigmoid backward computation
@triton.jit
def sigmoid_triton_bwd(x):
    a = sigmoid_triton_fwd(x)
    return a * (1 - a)

# Triton kernel for ReLU forward computation
@triton.jit
def relu_triton_fwd(x):
    return tl.maximum(0, x)

# Triton kernel for ReLU backward computation
@triton.jit
def relu_triton_bwd(x):
    return tl.where(x >= 0, 1.0, 0.0)

# Triton kernel for Leaky ReLU forward computation
