def leaky_relu_triton_fwd(x):
    return tl.where(x >= 0, x, 0.01 * x)

# Triton kernel for Leaky ReLU backward computation
@triton.jit
def leaky_relu_triton_bwd(x):
    return tl.where(x >= 0.0, 1.0, 0.01)

