import triton
import triton.language as tl

# Kernel with a single block of operations.
@triton.jit
def kernel_single(X, Y, BLOCK: tl.constexpr):
    # Load data from memory and store it to another location.
    x = tl.load(X + tl.arange(0, BLOCK))
    tl.store(Y + tl.arange(0, BLOCK), x)

# Kernel that calls an inlined device function.
@triton.jit
def kernel_call(X, Y, BLOCK: tl.constexpr):
    # Load data, process with inline function, and store results.
    x = tl.load(X + tl.arange(0, BLOCK))
    y = device_inline(x)
    tl.store(Y + tl.arange(0, BLOCK), y)

# Kernel with autotuning configuration for varying block size.
@triton.autotune(
    configs=[
        triton.Config({"BLOCK": 128}, num_warps=4),
    ],
    key=[],
)
@triton.jit
def kernel_autotune(X, Y, SIZE: tl.constexpr, BLOCK: tl.constexpr):
    # Iterate and process data in blocks.
    for i in range(0, SIZE, BLOCK):
        x = tl.load(X + i + tl.arange(0, BLOCK))
        tl.store(Y + i + tl.arange(0, BLOCK), x)

# Kernel performing matrix dot product and combining operations.
@triton.jit
def kernel_dot_combine(x):
    # Perform matrix operations and print results.
