    lt = value1 < value2
    gt = value1 > value2
    index_min = minimum(index1, index2)
    index_ret = where(lt, index1, where(gt, index2, index_min))
    value_ret = minimum(value1, value2)
    return value_ret, index_ret

@triton.jit
